      x: 1.0, y, w: 0.6, h: 1.05,
      fontFace: FONT_H, fontSize: 24, color: p.color, bold: true, valign: "middle", margin: 0
    });
    s.addText(p.title, {
      x: 1.7, y: y + 0.08, w: 7.4, h: 0.4,
      fontFace: FONT_H, fontSize: 18, color: C.white, bold: true, margin: 0
    });
    s.addText(p.desc, {
      x: 1.7, y: y + 0.48, w: 7.4, h: 0.5,
      fontFace: FONT_B, fontSize: 12, color: C.lightGray, margin: 0
    });
  });

  // Implication footer
  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 4.7, w: 8.6, h: 0.65, fill: { color: C.cardLight } });
  s.addText("Evaluated on WildClawBench with Qwen3-Max  \u2014  SkillClaw points toward continuously improving agent systems where skills are living artifacts, not static resources.", {
    x: 1.0, y: 4.7, w: 8.1, h: 0.65,
    fontFace: FONT_B, fontSize: 12, color: C.offWhite, valign: "middle", margin: 0
  });
}

