const pptxgen = require("pptxgenjs");

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.author = "SkillClaw Research";
pres.title = "SkillClaw: Collective Skill Evolution for Multi-User LLM Agent Ecosystems";

// Color palette: Midnight Executive with teal accent for technical/research feel
const C = {
  navy: "1A1F36",
  darkBg: "0F1629",
  card: "1E2640",
  cardLight: "232B45",
  teal: "00B4D8",
  tealDark: "0891B2",
  tealLight: "90E0EF",
  white: "FFFFFF",
  offWhite: "E8ECF1",
  lightGray: "94A3B8",
  midGray: "64748B",
  accept: "10B981",
  reject: "EF4444",
  amber: "F59E0B",
  lightBg: "F0F4F8",
  slideBg: "0B1120",
};

const FONT_H = "Georgia";
const FONT_B = "Calibri";

const mkShadow = () => ({ type: "outer", color: "000000", blur: 8, offset: 3, angle: 135, opacity: 0.25 });

// ===== SLIDE 1: Title =====
{
  const s = pres.addSlide();
  s.background = { color: C.slideBg };
  // Decorative top bar
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });
  // Subtle side accent
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0.06, w: 0.04, h: 5.565, fill: { color: C.teal, transparency: 40 } });

  s.addText("SKILLCLAW", {
    x: 0.8, y: 1.0, w: 8.4, h: 0.7,
    fontFace: FONT_H, fontSize: 18, color: C.teal, charSpacing: 8, bold: true, margin: 0
  });
  s.addText("Collective Skill Evolution for\nMulti-User LLM Agent Ecosystems", {
    x: 0.8, y: 1.7, w: 8.4, h: 1.6,
    fontFace: FONT_H, fontSize: 36, color: C.white, bold: true, lineSpacingMultiple: 1.15, margin: 0
  });
  s.addText("Let Skills Evolve Collectively with Agentic Evolver", {
    x: 0.8, y: 3.4, w: 8.4, h: 0.5,
    fontFace: FONT_B, fontSize: 16, color: C.tealLight, italic: true, margin: 0
  });
  s.addShape(pres.shapes.LINE, { x: 0.8, y: 4.1, w: 2.5, h: 0, line: { color: C.teal, width: 2 } });
  s.addText("arxiv.org/abs/2604.08377", {
    x: 0.8, y: 4.3, w: 4, h: 0.4,
    fontFace: FONT_B, fontSize: 12, color: C.lightGray, margin: 0
  });
  // Decorative circles
  s.addShape(pres.shapes.OVAL, { x: 8.3, y: 3.8, w: 1.2, h: 1.2, fill: { color: C.teal, transparency: 85 } });
  s.addShape(pres.shapes.OVAL, { x: 8.8, y: 4.2, w: 0.8, h: 0.8, fill: { color: C.tealDark, transparency: 75 } });
}

// ===== SLIDE 2: Problem =====
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });

  s.addText("Agent Skills Remain Static After Deployment", {
    x: 0.7, y: 0.35, w: 8.6, h: 0.6,
    fontFace: FONT_H, fontSize: 28, color: C.navy, bold: true, margin: 0
  });
  s.addText("Users Rediscover Solutions Independently", {
    x: 0.7, y: 0.95, w: 8.6, h: 0.4,
    fontFace: FONT_B, fontSize: 15, color: C.midGray, margin: 0
  });

  // Two-column comparison: Static vs Evolving
  const colW = 4.1, colY = 1.7, colH = 3.2;

  // Static column
  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: colY, w: colW, h: colH, fill: { color: C.white }, shadow: mkShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: colY, w: colW, h: 0.5, fill: { color: C.reject } });
  s.addText("STATIC SKILLS (Today)", {
    x: 0.7, y: colY, w: colW, h: 0.5,
    fontFace: FONT_B, fontSize: 13, color: C.white, bold: true, align: "center", valign: "middle"
  });
  s.addText([
    { text: "Skills manually installed from hub", options: { bullet: true, breakLine: true } },
    { text: "No learning from runtime experience", options: { bullet: true, breakLine: true } },
    { text: "Failures & recoveries repeat across users", options: { bullet: true, breakLine: true } },
    { text: "Memory-based methods: instance-specific, hard to generalize", options: { bullet: true, breakLine: true } },
    { text: "Knowledge never accumulates at system level", options: { bullet: true } },
  ], {
    x: 1.0, y: colY + 0.7, w: colW - 0.6, h: colH - 0.9,
    fontFace: FONT_B, fontSize: 13, color: C.navy, valign: "top", paraSpaceAfter: 6
  });

  // Evolving column
  s.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: colY, w: colW, h: colH, fill: { color: C.white }, shadow: mkShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 5.2, y: colY, w: colW, h: 0.5, fill: { color: C.accept } });
  s.addText("EVOLVING SKILLS (SkillClaw)", {
    x: 5.2, y: colY, w: colW, h: 0.5,
    fontFace: FONT_B, fontSize: 13, color: C.white, bold: true, align: "center", valign: "middle"
  });
  s.addText([
    { text: "Skills evolve from runtime interaction", options: { bullet: true, breakLine: true } },
    { text: "Cross-user trajectories aggregated", options: { bullet: true, breakLine: true } },
    { text: "Agentic evolver reasons over evidence", options: { bullet: true, breakLine: true } },
    { text: "Verified updates synchronized to all agents", options: { bullet: true, breakLine: true } },
    { text: "Shared ecosystem improves continuously", options: { bullet: true } },
  ], {
    x: 5.5, y: colY + 0.7, w: colW - 0.6, h: colH - 0.9,
    fontFace: FONT_B, fontSize: 13, color: C.navy, valign: "top", paraSpaceAfter: 6
  });

  // Arrow between columns
  s.addText("\u2192", {
    x: 4.5, y: 2.8, w: 1, h: 0.6,
    fontFace: FONT_B, fontSize: 32, color: C.teal, bold: true, align: "center", valign: "middle"
  });
}

// ===== SLIDE 3: Architecture Overview (diagram) =====
{
  const s = pres.addSlide();
  s.background = { color: C.slideBg };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });

  s.addText("Closed-Loop Pipeline: Multi-User Interaction to Shared Skill Evolution", {
    x: 0.7, y: 0.25, w: 8.6, h: 0.55,
    fontFace: FONT_H, fontSize: 22, color: C.white, bold: true, margin: 0
  });

  // Diagram: 4 stages in a loop
  const stages = [
    { label: "EVIDENCE", sub: "Analyze trajectories\nto identify patterns", color: "0E7490", x: 0.6, y: 1.3 },
    { label: "ATTRIBUTION", sub: "Diagnose root causes\nof failures & successes", color: "7C3AED", x: 3.0, y: 1.3 },
    { label: "EVOLUTION", sub: "Propose skill mutations\nvia open-ended reasoning", color: "059669", x: 5.4, y: 1.3 },
    { label: "DISTRIBUTION", sub: "Verify & synchronize\nupdated skills to agents", color: "D97706", x: 7.8, y: 1.3 },
  ];

  stages.forEach((st) => {
    s.addShape(pres.shapes.RECTANGLE, { x: st.x, y: st.y, w: 1.9, h: 1.7, fill: { color: C.card }, shadow: mkShadow() });
    s.addShape(pres.shapes.RECTANGLE, { x: st.x, y: st.y, w: 1.9, h: 0.06, fill: { color: st.color } });
    s.addText(st.label, {
      x: st.x, y: st.y + 0.2, w: 1.9, h: 0.4,
      fontFace: FONT_B, fontSize: 12, color: st.color, bold: true, align: "center", charSpacing: 2, margin: 0
    });
    s.addText(st.sub, {
      x: st.x + 0.1, y: st.y + 0.65, w: 1.7, h: 0.9,
      fontFace: FONT_B, fontSize: 10, color: C.offWhite, align: "center", valign: "top", margin: 0
    });
  });

  // Arrows between stages
  const arrowY = 2.05;
  [2.5, 4.9, 7.3].forEach(ax => {
    s.addText("\u25B6", { x: ax, y: arrowY, w: 0.5, h: 0.3, fontFace: FONT_B, fontSize: 16, color: C.teal, align: "center", valign: "middle" });
  });

  // Feedback loop arrow (bottom)
  s.addShape(pres.shapes.RECTANGLE, { x: 1.5, y: 3.25, w: 7.0, h: 0.04, fill: { color: C.teal, transparency: 50 } });
  s.addText("\u25C0  Closed-loop: updated skills feed back into multi-user interaction  \u25C0", {
    x: 1.5, y: 3.35, w: 7.0, h: 0.35,
    fontFace: FONT_B, fontSize: 10, color: C.tealLight, align: "center", margin: 0
  });

  // Bottom section: Multi-user interaction
  s.addShape(pres.shapes.RECTANGLE, { x: 0.6, y: 4.0, w: 8.8, h: 1.3, fill: { color: C.card }, shadow: mkShadow() });
  s.addText("MULTI-USER INTERACTION LAYER", {
    x: 0.6, y: 4.05, w: 8.8, h: 0.35,
    fontFace: FONT_B, fontSize: 11, color: C.teal, bold: true, align: "center", margin: 0
  });

  const agents = ["User A\nAgent", "User B\nAgent", "User C\nAgent", "...", "User N\nAgent"];
  agents.forEach((a, i) => {
    const ax = 1.2 + i * 1.7;
    s.addShape(pres.shapes.RECTANGLE, { x: ax, y: 4.45, w: 1.2, h: 0.65, fill: { color: C.cardLight } });
    s.addText(a, { x: ax, y: 4.45, w: 1.2, h: 0.65, fontFace: FONT_B, fontSize: 9, color: C.offWhite, align: "center", valign: "middle", margin: 0 });
  });
}

// ===== SLIDE 4: Agentic Evolver Pipeline =====
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });

  s.addText("Agentic Evolver: Three-Stage Pipeline", {
    x: 0.7, y: 0.3, w: 8.6, h: 0.55,
    fontFace: FONT_H, fontSize: 28, color: C.navy, bold: true, margin: 0
  });
  s.addText("Open-ended agent reasoning, not predefined update rules", {
    x: 0.7, y: 0.85, w: 8.6, h: 0.35,
    fontFace: FONT_B, fontSize: 14, color: C.midGray, italic: true, margin: 0
  });

  const pipes = [
    { num: "1", title: "Evidence", desc: "Analyze session trajectories preserving full action\u2013feedback causal chains to identify behavioral patterns across users", color: "0E7490", y: 1.6 },
    { num: "2", title: "Attribution", desc: "Diagnose root causes of failures and successes, separating generalizable improvements from idiosyncratic fixes", color: "7C3AED", y: 2.8 },
    { num: "3", title: "Evolution", desc: "Propose skill mutations \u2014 refining existing skills or creating new ones \u2014 then verify before merging into the shared repository", color: "059669", y: 4.0 },
  ];

  pipes.forEach(p => {
    // Number circle
    s.addShape(pres.shapes.OVAL, { x: 0.9, y: p.y + 0.1, w: 0.7, h: 0.7, fill: { color: p.color } });
    s.addText(p.num, {
      x: 0.9, y: p.y + 0.1, w: 0.7, h: 0.7,
      fontFace: FONT_H, fontSize: 22, color: C.white, bold: true, align: "center", valign: "middle"
    });
    // Card
    s.addShape(pres.shapes.RECTANGLE, { x: 2.0, y: p.y, w: 7.3, h: 0.95, fill: { color: C.white }, shadow: mkShadow() });
    s.addShape(pres.shapes.RECTANGLE, { x: 2.0, y: p.y, w: 0.07, h: 0.95, fill: { color: p.color } });
    s.addText(p.title, {
      x: 2.3, y: p.y + 0.05, w: 6.8, h: 0.35,
      fontFace: FONT_H, fontSize: 18, color: p.color, bold: true, margin: 0
    });
    s.addText(p.desc, {
      x: 2.3, y: p.y + 0.42, w: 6.8, h: 0.48,
      fontFace: FONT_B, fontSize: 12.5, color: C.navy, margin: 0
    });
  });

  // Connecting vertical line between circles
  s.addShape(pres.shapes.LINE, { x: 1.25, y: 2.4, w: 0, h: 0.4, line: { color: C.teal, width: 2, dashType: "dash" } });
  s.addShape(pres.shapes.LINE, { x: 1.25, y: 3.6, w: 0, h: 0.4, line: { color: C.teal, width: 2, dashType: "dash" } });
}

// ===== SLIDE 5: Cross-User Aggregation =====
{
  const s = pres.addSlide();
  s.background = { color: C.slideBg };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });

  s.addText("Cross-User Trajectory Aggregation", {
    x: 0.7, y: 0.3, w: 8.6, h: 0.55,
    fontFace: FONT_H, fontSize: 26, color: C.white, bold: true, margin: 0
  });
  s.addText("Exposing Skill Behavioral Boundaries", {
    x: 0.7, y: 0.85, w: 8.6, h: 0.35,
    fontFace: FONT_B, fontSize: 15, color: C.tealLight, margin: 0
  });

  // Key insight box
  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 1.5, w: 8.6, h: 0.8, fill: { color: C.card }, shadow: mkShadow() });
  s.addShape(pres.shapes.RECTANGLE, { x: 0.7, y: 1.5, w: 0.06, h: 0.8, fill: { color: C.amber } });
  s.addText("A single user rarely generates enough signal to separate a generalizable improvement from an idiosyncratic fix.", {
    x: 1.05, y: 1.5, w: 8.0, h: 0.8,
    fontFace: FONT_B, fontSize: 14, color: C.offWhite, italic: true, valign: "middle", margin: 0
  });

  // Compatible systems grid
  s.addText("Compatible Claw-Style Agent Systems", {
    x: 0.7, y: 2.6, w: 8.6, h: 0.35,
    fontFace: FONT_B, fontSize: 13, color: C.teal, bold: true, margin: 0
  });

  const systems = ["OpenClaw", "CoPaw", "IronClaw", "PicoClaw", "ZeroClaw", "NanoClaw", "NemoClaw"];
  systems.forEach((sys, i) => {
    const col = i % 4, row = Math.floor(i / 4);
    const sx = 0.7 + col * 2.3, sy = 3.1 + row * 0.6;
    s.addShape(pres.shapes.RECTANGLE, { x: sx, y: sy, w: 2.0, h: 0.45, fill: { color: C.cardLight } });
    s.addText(sys, { x: sx, y: sy, w: 2.0, h: 0.45, fontFace: FONT_B, fontSize: 12, color: C.offWhite, align: "center", valign: "middle" });
  });

  // Explanation
  s.addText("Different users exercising the same skill under diverse contexts produce complementary views of that skill\u2019s behavioral boundary, revealing both conditions under which it works and those under which it breaks.", {
    x: 0.7, y: 4.3, w: 8.6, h: 0.9,
    fontFace: FONT_B, fontSize: 13, color: C.lightGray, valign: "top", margin: 0
  });
}

// ===== SLIDE 6: Case Study - Creative Pipeline =====
{
  const s = pres.addSlide();
  s.background = { color: C.lightBg };
  s.addShape(pres.shapes.RECTANGLE, { x: 0, y: 0, w: 10, h: 0.06, fill: { color: C.teal } });

  s.addText("Case Study: Multimodal Creative Pipeline", {
    x: 0.7, y: 0.25, w: 8.6, h: 0.5,
    fontFace: FONT_H, fontSize: 24, color: C.navy, bold: true, margin: 0
  });
  s.addText("6-Day Evolution Log  \u2014  1 of 6 Accepted (Conservative Verification)", {
    x: 0.7, y: 0.75, w: 8.6, h: 0.35,
    fontFace: FONT_B, fontSize: 13, color: C.midGray, margin: 0
  });

  const headerOpts = { fill: { color: C.navy }, color: C.white, bold: true, fontSize: 11, fontFace: FONT_B, align: "center", valign: "middle" };
  const cellOpts = (clr) => ({ fontSize: 10, fontFace: FONT_B, color: C.navy, valign: "middle", fill: { color: clr || C.white } });

  const rows = [
    [
      { text: "Day", options: headerOpts },
      { text: "Candidate Skill", options: headerOpts },
      { text: "Outcome", options: headerOpts },
      { text: "Rationale", options: headerOpts },
    ],
    [
